package org.marketreview.nativeapp;
import android.database.*;import android.database.sqlite.*;import java.io.*;import java.util.*;import org.json.*;
final class MaterialLibraryStore {
 final File file;
 MaterialLibraryStore(File f)throws Exception{file=f;File parent=f.getAbsoluteFile().getParentFile();MaterialLibraryModel.require(parent.isDirectory()||parent.mkdirs(),"侧表目录无效");SQLiteDatabase db=open();try{int id;try(Cursor c=db.rawQuery("PRAGMA application_id",null)){c.moveToFirst();id=c.getInt(0);}if(id==0){try(Cursor c=db.rawQuery("SELECT count(*) FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' AND name!='android_metadata'",null)){c.moveToFirst();MaterialLibraryModel.require(c.getInt(0)==0,"非空未知库，拒绝重建");}db.beginTransaction();try{db.execSQL("CREATE TABLE records(id TEXT PRIMARY KEY NOT NULL,payload BLOB NOT NULL)");db.execSQL("CREATE TABLE heads(source_key TEXT PRIMARY KEY NOT NULL,id TEXT NOT NULL)");try(Cursor marker=db.rawQuery("PRAGMA application_id=1296843313",null)){marker.moveToFirst();}try(Cursor marker=db.rawQuery("PRAGMA application_id",null)){MaterialLibraryModel.require(marker.moveToFirst()&&marker.getInt(0)==1296843313,"侧表应用标记写入失败");}db.setTransactionSuccessful();}finally{db.endTransaction();}}else MaterialLibraryModel.require(id==1296843313,"侧表身份不支持");try(Cursor c=db.rawQuery("SELECT id,payload FROM records LIMIT 0",null)){}try(Cursor c=db.rawQuery("SELECT source_key,id FROM heads LIMIT 0",null)){} }finally{db.close();}}
 private SQLiteDatabase guardedOpen(int flags){
  if(file.exists())try(InputStream in=new FileInputStream(file)){
   byte[] header=new byte[16];int offset=0,n;while(offset<header.length&&(n=in.read(header,offset,header.length-offset))>0)offset+=n;
   if(offset!=16||!java.util.Arrays.equals(header,"SQLite format 3\000".getBytes(java.nio.charset.StandardCharsets.US_ASCII)))throw new android.database.sqlite.SQLiteDatabaseCorruptException("资料分类文件头无效；原文件保留");
  }catch(IOException error){throw new IllegalArgumentException("资料分类文件不可读取；原文件保留",error);}
  return SQLiteDatabase.openDatabase(file.getAbsolutePath(),null,flags,corrupt->{throw new android.database.sqlite.SQLiteDatabaseCorruptException("资料分类数据库损坏；拒绝自动删除或修复原文件");});
 }
 SQLiteDatabase open(){
  // Android may create android_metadata when opened writable: reject foreign files first.
  if(file.exists())try(SQLiteDatabase check=guardedOpen(SQLiteDatabase.OPEN_READONLY|SQLiteDatabase.NO_LOCALIZED_COLLATORS);Cursor marker=check.rawQuery("PRAGMA application_id",null)){
   MaterialLibraryModel.require(marker.moveToFirst()&&marker.getInt(0)==1296843313,"不是资料分类侧表，未写入或接管旧库");
  }
  return guardedOpen(SQLiteDatabase.OPEN_READWRITE|SQLiteDatabase.CREATE_IF_NECESSARY);
 }
 static JSONObject load(SQLiteDatabase db,String id)throws Exception{long length;try(Cursor c=db.rawQuery("SELECT length(CAST(payload AS BLOB)) FROM records WHERE id=?",new String[]{id})){if(!c.moveToNext())return new JSONObject();length=c.getLong(0);}MaterialLibraryModel.require(length>0&&length<=25*1024*1024,"侧表记录长度无效");ByteArrayOutputStream bytes=new ByteArrayOutputStream((int)length);for(int offset=0;offset<length;){int count=(int)Math.min(65536,length-offset);try(Cursor c=db.rawQuery("SELECT substr(CAST(payload AS BLOB),?,?) FROM records WHERE id=?",new String[]{String.valueOf(offset+1),String.valueOf(count),id})){MaterialLibraryModel.require(c.moveToNext(),"记录已变化");byte[] part=c.getBlob(0);MaterialLibraryModel.require(part!=null&&part.length==count,"分块不完整");bytes.write(part);offset+=count;}}String s=java.nio.charset.StandardCharsets.UTF_8.newDecoder().onMalformedInput(java.nio.charset.CodingErrorAction.REPORT).decode(java.nio.ByteBuffer.wrap(bytes.toByteArray())).toString();new EvidenceReviewModel.Syntax(s).check();return new JSONObject(s);}
 static String head(SQLiteDatabase db,String key){try(Cursor c=db.rawQuery("SELECT id FROM heads WHERE source_key=?",new String[]{key})){return c.moveToNext()?c.getString(0):"";}}
 static void insert(SQLiteDatabase db,JSONObject r)throws Exception{JSONObject old=load(db,r.getString("id"));MaterialLibraryModel.require(old.length()==0||EvidenceReviewModel.canonical(old).equals(EvidenceReviewModel.canonical(r)),"同分类ID冲突；未覆盖");if(old.length()==0)db.execSQL("INSERT INTO records(id,payload)VALUES(?,?)",new Object[]{r.getString("id"),MaterialLibraryModel.json(r)});}
 JSONObject heads()throws Exception{SQLiteDatabase db=open();try{JSONObject result=new JSONObject();List<String[]> rows=new ArrayList<>();try(Cursor c=db.rawQuery("SELECT source_key,id FROM heads",null)){while(c.moveToNext())rows.add(new String[]{c.getString(0),c.getString(1)});}for(String[] row:rows){JSONObject r=MaterialLibraryModel.validate(load(db,row[1]));MaterialLibraryModel.require(MaterialLibraryModel.key(r.getJSONObject("reference")).equals(row[0]),"分类当前版本索引不符");result.put(row[0],r);}return result;}finally{db.close();}}
 JSONArray history()throws Exception{SQLiteDatabase db=open();try{List<String> ids=new ArrayList<>();try(Cursor c=db.rawQuery("SELECT id FROM records WHERE id!='private-state' ORDER BY rowid DESC",null)){while(c.moveToNext())ids.add(c.getString(0));}JSONArray out=new JSONArray();for(String id:ids)out.put(MaterialLibraryModel.validate(load(db,id)));return out;}finally{db.close();}}
 void save(JSONObject input,String expected)throws Exception{JSONObject r=MaterialLibraryModel.validate(input);MaterialLibraryModel.require(r.optString("parentId").equals(expected),"分类父版本不符");String key=MaterialLibraryModel.key(r.getJSONObject("reference"));SQLiteDatabase db=open();try{db.beginTransaction();try{MaterialLibraryModel.require(head(db,key).equals(expected),"其他入口已改变分类；草稿保留，未覆盖");insert(db,r);db.execSQL("INSERT OR REPLACE INTO heads(source_key,id)VALUES(?,?)",new Object[]{key,r.getString("id")});db.setTransactionSuccessful();}finally{db.endTransaction();}}finally{db.close();}}
 JSONObject preview(String text)throws Exception{MaterialLibraryModel.require(text.getBytes(java.nio.charset.StandardCharsets.UTF_8).length<=25*1024*1024,"导入超过25MiB");new EvidenceReviewModel.Syntax(text).check();JSONObject o=new JSONObject(text);MaterialLibraryModel.require(o.optString("schema").equals("material-library-v1")&&o.optJSONArray("records")!=null&&o.optJSONObject("heads")!=null,"分类备份schema不支持");Map<String,JSONObject> rows=new HashMap<>();JSONArray a=o.getJSONArray("records");for(int i=0;i<a.length();i++){JSONObject r=MaterialLibraryModel.validate(a.getJSONObject(i));MaterialLibraryModel.require(!rows.containsKey(r.getString("id")),"分类ID重复");rows.put(r.getString("id"),r);}for(JSONObject r:rows.values()){String parent=r.optString("parentId");MaterialLibraryModel.require(parent.isEmpty()||(rows.containsKey(parent)&&MaterialLibraryModel.key(rows.get(parent).getJSONObject("reference")).equals(MaterialLibraryModel.key(r.getJSONObject("reference")))),"分类历史链缺失或跨来源");}JSONObject hs=o.getJSONObject("heads");Iterator<String> keys=hs.keys();while(keys.hasNext()){String key=keys.next(),id=hs.getString(key);MaterialLibraryModel.require(rows.containsKey(id)&&MaterialLibraryModel.key(rows.get(id).getJSONObject("reference")).equals(key),"分类head引用不符");}return new JSONObject().put("backup",o).put("digest",MaterialLibraryModel.fingerprint(o)).put("mergePolicy","keep-existing");}
 void merge(JSONObject p)throws Exception{MaterialLibraryModel.require(p.optString("mergePolicy").equals("keep-existing")&&p.optString("digest").equals(MaterialLibraryModel.fingerprint(p.getJSONObject("backup"))),"分类预览已改变");JSONObject verified=preview(MaterialLibraryModel.json(p.getJSONObject("backup"))),backup=verified.getJSONObject("backup");SQLiteDatabase db=open();try{db.beginTransaction();try{JSONArray a=backup.getJSONArray("records");for(int i=0;i<a.length();i++)insert(db,a.getJSONObject(i));JSONObject hs=backup.getJSONObject("heads");Iterator<String> keys=hs.keys();while(keys.hasNext()){String key=keys.next();db.execSQL("INSERT OR IGNORE INTO heads(source_key,id)VALUES(?,?)",new Object[]{key,hs.getString(key)});}db.setTransactionSuccessful();}finally{db.endTransaction();}}finally{db.close();}}
 String backup()throws Exception{SQLiteDatabase db=open();try{db.beginTransaction();try{List<String> keys=new ArrayList<>();try(Cursor c=db.rawQuery("SELECT id FROM records WHERE id!='private-state' ORDER BY rowid DESC",null)){while(c.moveToNext())keys.add(c.getString(0));}JSONArray a=new JSONArray();for(String id:keys)a.put(MaterialLibraryModel.validate(load(db,id)));JSONObject ids=new JSONObject();try(Cursor c=db.rawQuery("SELECT source_key,id FROM heads",null)){while(c.moveToNext())ids.put(c.getString(0),c.getString(1));}String text=MaterialLibraryModel.json(new JSONObject().put("schema","material-library-v1").put("records",a).put("heads",ids));db.setTransactionSuccessful();return text;}finally{db.endTransaction();}}finally{db.close();}} JSONObject state()throws Exception{SQLiteDatabase db=open();try{db.beginTransaction();try{JSONObject s=load(db,"private-state");db.setTransactionSuccessful();return s;}finally{db.endTransaction();}}finally{db.close();}}
 String saveState(JSONObject s,String expected)throws Exception{SQLiteDatabase db=open();try{db.beginTransaction();try{JSONObject old=load(db,"private-state");MaterialLibraryModel.require(old.optString("revision").equals(expected),"另一入口已更改资料草稿；未覆盖");String revision=UUID.randomUUID().toString();JSONObject r=new JSONObject(MaterialLibraryModel.json(s)).put("revision",revision);db.execSQL("INSERT OR REPLACE INTO records(id,payload)VALUES('private-state',?)",new Object[]{MaterialLibraryModel.json(r)});db.setTransactionSuccessful();return revision;}finally{db.endTransaction();}}finally{db.close();}}
}
